//! Compile a real ARMv6-M firmware with `clang` and execute it on this core.
//!
//! This is the "real firmware trace" from the M0 definition of done: instead
//! of hand-assembled bytes, the code is generated by the LLVM backend and
//! executed through the simulator. The tests build the firmware with `clang`
//! and extract the raw `.text` with `objcopy`; they skip (with a note) if the
//! toolchain binaries are not available.

use std::collections::HashMap;
use std::env;
use std::fs;
use std::path::{Path, PathBuf};
use std::process::Command;
use std::sync::atomic::{AtomicUsize, Ordering};

use vioarm_core::board;
use vioarm_core::device::systick::SysTick;
use vioarm_core::error::HaltCause;
use vioarm_core::loader::load_flat;
use vioarm_core::machine::Machine;
use vioarm_core::mem::bus::Bus;
use vioarm_core::mem::flat::FlatMemory;
use vioarm_core::mem::system::SystemMemory;

const FLASH: u32 = 0x0000_0000;
const RAM: u32 = 0x2000_0000;
const FLASH_LEN: u32 = 0x10000;
const RAM_LEN: u32 = 0x10000;
const CODE_BASE: u32 = 0x0000_0100;
/// The USB firmware is entered via IRQ 67, whose vector (exception 83) sits
/// at `FLASH + 83 * 4 == 0x14C` — inside the region `CODE_BASE` occupies.
/// Load that image higher so the vector table write cannot clobber code.
const USB_CODE_BASE: u32 = 0x0000_1000;
/// The initial stack pointer: high enough for the harness stacks yet within
/// every board's RAM (the smallest, the F103's 20 KiB, ends at `0x2000_5000`).
const INIT_SP: u32 = 0x2000_4000;

const IN_ADDR: u32 = RAM;
const SUM_ADDR: u32 = RAM + 4;
const TAG_ADDR: u32 = RAM + 8;
const MARKER_ADDR: u32 = RAM;

/// A small freestanding firmware: read an input, sum 1..=n in a loop that
/// stays a loop under `-O0` (and which therefore needs no libc helpers), store
/// the sum and a sentinel, then `bkpt`.
const FIRMWARE: &str = r#"
#define IN_ADDR  0x20000000u
#define SUM_ADDR 0x20000004u
#define TAG_ADDR 0x20000008u

__attribute__((noinline)) static unsigned sum1to(unsigned n) {
    unsigned s = 0;
    for (unsigned i = 1; i <= n; ++i) s += i;
    return s;
}

void reset(void) {
    unsigned n = *(volatile unsigned *)IN_ADDR;
    unsigned s = sum1to(n);
    *(volatile unsigned *)SUM_ADDR = s;
    *(volatile unsigned *)TAG_ADDR = 0xdeadbeefu;
    __asm__ volatile("bkpt #0");
}
"#;

/// A firmware that arms `SysTick` and lets the handler run three times before
/// stopping the timer and halting.
const SYSTICK_FIRMWARE: &str = r#"
#define TICKS    0x20000000u
#define COUNT    0x20000004u
#define PERIOD   0x20000008u
#define SYST_CSR 0xE000E010u
#define SYST_RVR 0xE000E014u
#define SYST_CVR 0xE000E018u

void SysTick_Handler(void) {
    (*(volatile unsigned *)TICKS)++;
}

void reset(void) {
    *(volatile unsigned *)SYST_RVR = *(volatile unsigned *)PERIOD - 1;
    *(volatile unsigned *)SYST_CVR = 0;
    *(volatile unsigned *)SYST_CSR = 0x7; /* ENABLE | TICKINT | CLKSOURCE */
    while (*(volatile unsigned *)TICKS < 3) { }
    *(volatile unsigned *)SYST_CSR = 0; /* stop the timer */
    *(volatile unsigned *)COUNT = *(volatile unsigned *)TICKS;
    __asm__ volatile("bkpt #0");
}
"#;

/// The same timer exercise, but the thread sits in `WFI` between interrupts.
/// A sleeping core must still tick `SysTick` and be woken by it, then resume
/// the instruction after the `WFI`.
const WFI_SYSTICK_FIRMWARE: &str = r#"
#define TICKS    0x20000000u
#define COUNT    0x20000004u
#define PERIOD   0x20000008u
#define SYST_CSR 0xE000E010u
#define SYST_RVR 0xE000E014u
#define SYST_CVR 0xE000E018u

void SysTick_Handler(void) {
    (*(volatile unsigned *)TICKS)++;
}

void reset(void) {
    *(volatile unsigned *)SYST_RVR = *(volatile unsigned *)PERIOD - 1;
    *(volatile unsigned *)SYST_CVR = 0;
    *(volatile unsigned *)SYST_CSR = 0x7; /* ENABLE | TICKINT | CLKSOURCE */
    while (*(volatile unsigned *)TICKS < 3) {
        __asm__ volatile("wfi");
    }
    *(volatile unsigned *)SYST_CSR = 0; /* stop the timer */
    *(volatile unsigned *)COUNT = *(volatile unsigned *)TICKS;
    __asm__ volatile("bkpt #0");
}
"#;

/// A firmware that arms the independent watchdog with a short timeout, never
/// refreshes it, and relies on the watchdog reset to reboot the part. A boot
/// counter in RAM survives those resets, so the test can count how many times
/// the watchdog actually fired.
const IWDG_FIRMWARE: &str = r"
#define BOOTCOUNT 0x20000000u
#define IWDG_KR  0x40003000u
#define IWDG_RLR 0x40003008u

void reset(void) {
    unsigned n = (*(volatile unsigned *)BOOTCOUNT)++;
    if (n < 3) {
        *(volatile unsigned *)IWDG_KR = 0x5555u;  /* unlock RLR */
        *(volatile unsigned *)IWDG_RLR = 0x10u;   /* short timeout */
        *(volatile unsigned *)IWDG_KR = 0xCCCCu;  /* start; never refresh */
        while (1) { }
    }
    /* Three watchdog resets observed: arm a long timeout and spin. */
    *(volatile unsigned *)IWDG_KR = 0x5555u;
    *(volatile unsigned *)IWDG_RLR = 0xFFFu;
    *(volatile unsigned *)IWDG_KR = 0xCCCCu;
    while (1) { }
}
";

/// A firmware that drives GPIO outputs, reads back host-driven inputs, and
/// transmits a line of text on the virtual UART before halting.
const IO_FIRMWARE: &str = r#"
#define OUT_SNAPSHOT 0x20000000u
#define IN_SNAPSHOT  0x20000004u
#define UART_DR 0x40001000u
#define UART_FR 0x40001004u
#define GPIO_DIR 0x40000000u
#define GPIO_OUT 0x40000004u
#define GPIO_IN  0x40000008u

static void putc(unsigned c) {
    while (!(*(volatile unsigned *)UART_FR & 1u)) { }
    *(volatile unsigned *)UART_DR = c;
}

void reset(void) {
    *(volatile unsigned *)GPIO_DIR = 0xFFu; /* pins 0..7 outputs */
    *(volatile unsigned *)GPIO_OUT = 0xAAu;
    *(volatile unsigned *)OUT_SNAPSHOT = *(volatile unsigned *)GPIO_OUT;
    *(volatile unsigned *)IN_SNAPSHOT = *(volatile unsigned *)GPIO_IN;
    putc('H'); putc('i'); putc('!'); putc('\n');
    __asm__ volatile("bkpt #0");
}
"#;

static SEQ: AtomicUsize = AtomicUsize::new(0);
/// Find an executable by name on `PATH` (trying `name.exe` on Windows, where
/// `clang` is installed as `clang.exe`).
fn which(name: &str) -> Option<PathBuf> {
    if let Some(found) = env::var_os("PATH").and_then(|paths| {
        env::split_paths(&paths).find_map(|dir| {
            let plain = dir.join(name);
            if plain.is_file() {
                return Some(plain);
            }
            let exe = dir.join(format!("{name}.exe"));
            if exe.is_file() {
                return Some(exe);
            }
            None
        })
    }) {
        return Some(found);
    }
    for dir in [
        "/usr/lib/llvm-21/bin",
        "/usr/lib/llvm-20/bin",
        "/usr/lib/llvm-19/bin",
        "/usr/lib/llvm-18/bin",
    ] {
        let candidate = Path::new(dir).join(name);
        if candidate.is_file() {
            return Some(candidate);
        }
    }
    None
}

/// Run a tool, capturing stdout; `Err` on spawn or non-zero exit.
fn run(tool: &Path, args: &[&str]) -> Result<String, String> {
    let out = Command::new(tool)
        .args(args)
        .output()
        .map_err(|e| format!("cannot run {}: {e}", tool.display()))?;
    if !out.status.success() {
        let stderr = String::from_utf8_lossy(&out.stderr);
        return Err(format!("{} failed: {stderr}", tool.display()));
    }
    Ok(String::from_utf8_lossy(&out.stdout).into_owned())
}

/// Compile `source` and return `(.text bytes, symbol -> offset within .text)`.
fn build_firmware(source: &str) -> Result<(Vec<u8>, HashMap<String, u32>), String> {
    build_firmware_with_includes(source, &[])
}

/// Like [`build_firmware`], but adds `includes` as `-I` search paths.
fn build_firmware_with_includes(
    source: &str,
    includes: &[&str],
) -> Result<(Vec<u8>, HashMap<String, u32>), String> {
    build_firmware_for(source, includes, "thumbv6m-none-eabi", "cortex-m0", false)
}

/// Like [`build_firmware_with_includes`], but for an ARMv7-M (Cortex-M3/M4)
/// target, so the firmware can use the v7-M fault/FP features (`SHCSR`,
/// `CPACR`, VFP).
fn build_firmware_v7m_with_includes(
    source: &str,
    includes: &[&str],
) -> Result<(Vec<u8>, HashMap<String, u32>), String> {
    build_firmware_for(source, includes, "thumbv7em-none-eabi", "cortex-m4", false)
}

/// Like [`build_firmware_v7m_with_includes`], but with the FPU enabled so
/// inline asm may reference VFP registers (`s0`, `d0`, ...). The ABI stays
/// soft so no FP args/returns creep into the integer-only handlers.
fn build_firmware_v7m_fp_with_includes(
    source: &str,
    includes: &[&str],
) -> Result<(Vec<u8>, HashMap<String, u32>), String> {
    build_firmware_for(source, includes, "thumbv7em-none-eabi", "cortex-m4", true)
}

fn build_firmware_for(
    source: &str,
    includes: &[&str],
    target: &str,
    cpu: &str,
    vfp: bool,
) -> Result<(Vec<u8>, HashMap<String, u32>), String> {
    let clang = which("clang").ok_or_else(|| "clang not found on PATH".to_string())?;
    let objcopy = which("llvm-objcopy")
        .or_else(|| which("objcopy"))
        .ok_or_else(|| "objcopy not found on PATH".to_string())?;
    let nm = which("llvm-nm")
        .or_else(|| which("nm"))
        .ok_or_else(|| "nm not found on PATH".to_string())?;

    let dir = env::temp_dir().join(format!("vioarm-fw-{}", SEQ.fetch_add(1, Ordering::Relaxed)));
    fs::create_dir_all(&dir).map_err(|e| format!("cannot create {}: {e}", dir.display()))?;
    let src = dir.join("firmware.c");
    let obj = dir.join("firmware.o");
    fs::write(&src, source).map_err(|e| e.to_string())?;

    let src = src.to_str().ok_or("temp path not UTF-8")?;
    let obj = obj.to_str().ok_or("temp path not UTF-8")?;
    let target_arg = format!("--target={target}");
    let cpu_arg = format!("-mcpu={cpu}");
    let float_args: [&str; 2] = if vfp {
        ["-mfloat-abi=softfp", "-mfpu=fpv4-sp-d16"]
    } else {
        ["-mfloat-abi=soft", "-mfpu=none"]
    };
    let mut args = vec![
        target_arg.as_str(),
        cpu_arg.as_str(),
        "-mthumb",
        "-ffreestanding",
        "-nostdlib",
        "-O0",
        "-g0",
        "-c",
        src,
        "-o",
        obj,
    ];
    for f in float_args {
        args.push(f);
    }
    for inc in includes {
        args.push("-I");
        args.push(inc);
    }
    run(&clang, &args)?;

    let listing = run(&nm, &["-n", obj])?;
    let mut symbols = HashMap::new();
    for line in listing.lines() {
        let mut it = line.split_whitespace();
        let (Some(offset), Some(_ty), Some(name)) = (it.next(), it.next(), it.next()) else {
            continue;
        };
        if let Ok(off) = u32::from_str_radix(offset, 16) {
            symbols.insert(name.to_string(), off);
        }
    }

    let bin = dir.join("firmware.bin");
    let bin = bin.to_str().ok_or("temp path not UTF-8")?;
    run(
        &objcopy,
        &["--output-target=binary", "-j", ".text", obj, bin],
    )?;
    let bytes = fs::read(bin).map_err(|e| e.to_string())?;
    Ok((bytes, symbols))
}

/// A firmware image produced by `clang -O0` runs to its `bkpt` and leaves the
/// computed results where the C source wrote them.
#[test]
fn clang_compiled_firmware_runs() {
    let (code, symbols) = match build_firmware(FIRMWARE) {
        Ok(image) => image,
        Err(why) => {
            eprintln!("skipping real-firmware test: {why}");
            return;
        }
    };
    let entry = *symbols.get("reset").expect("no reset symbol");
    assert!(!code.is_empty(), "compiled .text must not be empty");

    let mut m = Machine::new(FlatMemory::with_layout(
        &[FLASH, RAM],
        &[FLASH_LEN, RAM_LEN],
    ));
    m.load_image(&load_flat(CODE_BASE, &code));
    {
        let mem = m.core.mem();
        mem.write_word(FLASH, INIT_SP).unwrap();
        mem.write_word(FLASH + 4, (CODE_BASE + entry) | 1).unwrap();
        mem.write_word(FLASH + 8, 0).unwrap();
        mem.write_word(FLASH + 12, 0).unwrap();
        mem.write_word(IN_ADDR, 7).unwrap();
    }
    m.reset().expect("reset from vector table");
    let err = m.run(10_000);
    assert_eq!(err, Err(HaltCause::NonThumbTarget));
    // sum(7) = 1+2+3+4+5+6+7 == 28.
    assert_eq!(m.core.mem().read_word(SUM_ADDR).unwrap(), 28);
    assert_eq!(m.core.mem().read_word(TAG_ADDR).unwrap(), 0xdead_beef);
}

/// A clang-compiled `SysTick_Handler` fires repeatedly off a wrapped `SysTick`
/// and returns to the interrupted thread.
#[test]
fn systick_handler_fires_and_returns() {
    let (code, symbols) = match build_firmware(SYSTICK_FIRMWARE) {
        Ok(image) => image,
        Err(why) => {
            eprintln!("skipping systick test: {why}");
            return;
        }
    };
    let entry = *symbols.get("reset").expect("no reset symbol");
    let systick = *symbols
        .get("SysTick_Handler")
        .expect("no SysTick_Handler symbol");
    assert!(!code.is_empty(), "compiled .text must not be empty");

    let mut sysmem = SystemMemory::new(FlatMemory::with_layout(
        &[FLASH, RAM],
        &[FLASH_LEN, RAM_LEN],
    ));
    sysmem.attach(Box::new(SysTick::new()));
    let mut m = Machine::new(sysmem);
    m.load_image(&load_flat(CODE_BASE, &code));
    {
        let mem = m.core.mem();
        mem.write_word(FLASH, INIT_SP).unwrap();
        mem.write_word(FLASH + 4, (CODE_BASE + entry) | 1).unwrap();
        mem.write_word(FLASH + 8, 0).unwrap();
        mem.write_word(FLASH + 12, 0).unwrap();
        // Vector 15 (SysTick) at FLASH + 15 * 4.
        mem.write_word(FLASH + 60, (CODE_BASE + systick) | 1)
            .unwrap();
        mem.write_word(RAM + 8, 20).unwrap(); // PERIOD
    }
    m.reset().expect("reset from vector table");
    let err = m.run(100_000);
    assert_eq!(err, Err(HaltCause::NonThumbTarget));
    // The handler ran at least three times before the firmware stopped it.
    let ticks = m.core.mem().read_word(RAM).unwrap();
    assert!(ticks >= 3, "handler ran only {ticks} times");
    assert_eq!(m.core.mem().read_word(RAM + 4).unwrap(), ticks);
}

/// A firmware that sits in `WFI` between `SysTick` interrupts is woken by each
/// one and resumes the instruction after the `WFI`, exactly like the busy-wait
/// variant above.
#[test]
fn wfi_sleeps_until_systick_wakes() {
    let (code, symbols) = match build_firmware(WFI_SYSTICK_FIRMWARE) {
        Ok(image) => image,
        Err(why) => {
            eprintln!("skipping wfi-systick test: {why}");
            return;
        }
    };
    let entry = *symbols.get("reset").expect("no reset symbol");
    let systick = *symbols
        .get("SysTick_Handler")
        .expect("no SysTick_Handler symbol");
    assert!(!code.is_empty(), "compiled .text must not be empty");

    let mut sysmem = SystemMemory::new(FlatMemory::with_layout(
        &[FLASH, RAM],
        &[FLASH_LEN, RAM_LEN],
    ));
    sysmem.attach(Box::new(SysTick::new()));
    let mut m = Machine::new(sysmem);
    m.load_image(&load_flat(CODE_BASE, &code));
    {
        let mem = m.core.mem();
        mem.write_word(FLASH, INIT_SP).unwrap();
        mem.write_word(FLASH + 4, (CODE_BASE + entry) | 1).unwrap();
        // Vector 15 (SysTick) at FLASH + 15 * 4.
        mem.write_word(FLASH + 60, (CODE_BASE + systick) | 1)
            .unwrap();
        mem.write_word(RAM + 8, 20).unwrap(); // PERIOD
    }
    m.reset().expect("reset from vector table");
    let err = m.run(100_000);
    assert_eq!(err, Err(HaltCause::NonThumbTarget));
    let ticks = m.core.mem().read_word(RAM).unwrap();
    assert!(ticks >= 3, "handler ran only {ticks} times");
    assert_eq!(m.core.mem().read_word(RAM + 4).unwrap(), ticks);
}

/// An un-refreshed IWDG underflow resets the whole machine; the firmware's
/// reset handler re-runs and the RAM boot counter proves how many resets the
/// watchdog caused.
#[test]
fn iwdg_underflow_resets_the_machine() {
    let (code, symbols) = match build_firmware(IWDG_FIRMWARE) {
        Ok(image) => image,
        Err(why) => {
            eprintln!("skipping iwdg-reset test: {why}");
            return;
        }
    };
    let entry = *symbols.get("reset").expect("no reset symbol");
    assert!(!code.is_empty(), "compiled .text must not be empty");

    let mut m = Machine::new(board::stm32f103());
    m.load_image(&load_flat(CODE_BASE, &code));
    {
        let mem = m.core.mem();
        mem.write_word(board::FLASH, INIT_SP).unwrap();
        mem.write_word(board::FLASH + 4, (CODE_BASE + entry) | 1)
            .unwrap();
        mem.write_word(board::RAM, 0).unwrap(); // BOOTCOUNT
    }
    m.reset().expect("reset from vector table");
    // The first three boots arm a 0x10-timeout IWDG and are reset by it; the
    // fourth boots into the 0xFFF timeout, so the budget cuts the run short
    // there. Four boots means the watchdog reset the machine three times.
    // With `b .` now 3c (vs 1c), the 0xFFF timeout (4095c) is ~1365 `b .` loops,
    // so 2000 cycles covers an extra reset.
    let err = m.run(2000);
    assert_eq!(err, Err(HaltCause::CycleBudgetExhausted));
    let boots = m.core.mem().read_word(board::RAM).unwrap();
    assert!(
        boots >= 4,
        "the watchdog reset the machine at least three times, got {boots}"
    );
}

/// On the virtual board, firmware drives GPIO outputs, reads back
/// host-injected inputs, and emits text on the UART.
#[test]
fn virtual_board_io_round_trips() {
    let (code, symbols) = match build_firmware(IO_FIRMWARE) {
        Ok(image) => image,
        Err(why) => {
            eprintln!("skipping virtual-board test: {why}");
            return;
        }
    };
    let entry = *symbols.get("reset").expect("no reset symbol");
    assert!(!code.is_empty(), "compiled .text must not be empty");

    let mut m = Machine::new(board::virtual_board());
    m.load_image(&load_flat(CODE_BASE, &code));
    {
        let mem = m.core.mem();
        mem.write_word(board::FLASH, INIT_SP).unwrap();
        mem.write_word(board::FLASH + 4, (CODE_BASE + entry) | 1)
            .unwrap();
    }
    m.reset().expect("reset from vector table");
    // Host stimulus: pins 8..15 are high while the firmware runs.
    for device in m.core.mem().devices_mut() {
        device.drive_inputs(0x0000_5A00);
    }
    let err = m.run(10_000);
    assert_eq!(err, Err(HaltCause::NonThumbTarget));
    // GPIO: the output latch was driven and read back; the host-driven inputs
    // were observed on the IN register.
    assert_eq!(m.core.mem().read_word(board::RAM).unwrap(), 0xAA);
    assert_eq!(m.core.mem().read_word(board::RAM + 4).unwrap(), 0x5A00);
    // UART: the four transmitted characters reached the host channel.
    let mut tx = Vec::new();
    for device in m.core.mem().devices_mut() {
        tx.extend(device.drain_output());
    }
    assert_eq!(tx, b"Hi!\n");
}

/// Firmware that executes a Thumb-2-only `MOVW` (encoded for a Cortex-M4)
/// followed by a marker store and a `bkpt`.
const THUMB2_FIRMWARE: &str = r#"
#define MARKER 0x20000000u

void reset(void) {
    __asm__ volatile("movw r0, #0x1234");
    *(volatile unsigned *)MARKER = 0xdeadbeefu;
    __asm__ volatile("bkpt #0");
}
"#;

/// ARMv6-M (Cortex-M0/M0+) firmware compiled for a Cortex-M4 target must have
/// its first Thumb-2 instruction rejected: the v6-m core treats `MOVW` as
/// undefined and escalates straight to `HardFault`, never reaching the marker
/// store after it. This is the real-firmware side of the decoder-subset
/// hardening: the machine halts before `MARKER` is written.
#[test]
fn cortex_m0_rejects_thumb2_firmware() {
    let (code, symbols) = match build_firmware_v7m_with_includes(THUMB2_FIRMWARE, &[]) {
        Ok(image) => image,
        Err(why) => {
            eprintln!("skipping thumb2-rejection test: {why}");
            return;
        }
    };
    let entry = *symbols.get("reset").expect("no reset symbol");
    assert!(!code.is_empty(), "compiled .text must not be empty");

    let mut m = Machine::new(board::cortex_m0());
    m.load_image(&load_flat(CODE_BASE, &code));
    {
        let mem = m.core.mem();
        mem.write_word(FLASH, INIT_SP).unwrap();
        mem.write_word(FLASH + 4, (CODE_BASE + entry) | 1).unwrap();
    }
    m.reset().expect("reset from vector table");
    let err = m.run(10_000);
    // The escalated HardFault reads its (unset) vector entry and halts.
    assert_eq!(err, Err(HaltCause::NonThumbTarget));
    assert_eq!(
        m.core.mem().read_word(MARKER_ADDR).unwrap(),
        0,
        "the Thumb-2 MOVW must not execute on the ARMv6-M core"
    );
}

/// Real CMSIS-style firmware against the STM32F103 device header from the
/// Keil pack: clock gates, GPIO config via `BSRR`, `USART1` transmit plus an
/// interrupt-driven receive, and a counting `TIM2` — all exercised through
/// the real peripheral registers.
///
/// The firmware is kept self-contained (no string literals or static
/// variables): the harness extracts raw `.text` from the object, so any
/// `.rodata`/`.bss` relocation would collapse to address zero. Characters and
/// the RX scratch live at absolute addresses instead.
const STM32_F103_FIRMWARE: &str = r#"
#define STM32F10X_HD
#include "stm32f10x.h"

#define OUT_SNAPSHOT 0x20000000u
#define RX_SNAPSHOT  0x20000004u
#define TIM_SNAPSHOT 0x20000008u
#define RX_WORD      (*(volatile unsigned *)0x2000000Cu)

void USART1_IRQHandler(void) {
    if (USART1->SR & USART_SR_RXNE) {
        RX_WORD = USART1->DR;
    }
}

static void tx_byte(unsigned c) {
    while (!(USART1->SR & USART_SR_TXE)) { }
    USART1->DR = c;
}

void reset(void) {
    /* 1. Clock gates: GPIOA + AFIO + USART1 on APB2, TIM2 on APB1. */
    RCC->APB2ENR |= RCC_APB2ENR_IOPAEN | RCC_APB2ENR_AFIOEN | RCC_APB2ENR_USART1EN;
    RCC->APB1ENR |= RCC_APB1ENR_TIM2EN;

    /* 2. PA9 = USART1_TX (alternate push-pull 50 MHz), PA10 = USART1_RX. */
    GPIOA->CRH = (GPIOA->CRH & ~(0xFu << (1 * 4))) | (0xBu << (1 * 4));
    GPIOA->CRH = (GPIOA->CRH & ~(0xFu << (2 * 4))) | (0x4u << (2 * 4));
    GPIOA->BSRR = (1u << 0); /* drive PA0 high */

    /* 3. USART1 at 8 MHz HSI / 9600 baud: BRR = 8e6 / 9600 = 833. */
    USART1->BRR = 0x341;
    USART1->CR1 = USART_CR1_UE | USART_CR1_TE | USART_CR1_RE;

    /* 4. TIM2 free-runs (PSC 0, 16-bit ARR in the F1 header). */
    TIM2->ARR = 0xFFFFu;
    TIM2->PSC = 0;
    TIM2->EGR = TIM_EGR_UG;
    TIM2->CR1 = TIM_CR1_CEN;

    /* 5. Arm the RX interrupt (IRQ 37, exception vector 53). */
    NVIC->ISER[1] = 1u << (USART1_IRQn - 32);
    USART1->CR1 |= USART_CR1_RXNEIE;

    /* 6. Transmit a line. */
    tx_byte('o'); tx_byte('k'); tx_byte('!'); tx_byte('\n');

    /* 7. Wait for the host-injected byte to arrive through the IRQ. */
    while (!RX_WORD) { }

    *(volatile unsigned *)OUT_SNAPSHOT = GPIOA->ODR;
    *(volatile unsigned *)RX_SNAPSHOT = RX_WORD;
    *(volatile unsigned *)TIM_SNAPSHOT = TIM2->CNT;
    __asm__ volatile("bkpt #0");
}
"#;

/// Compile [`STM32_F103_FIRMWARE`], boot it on `board`, inject a received byte,
/// and return `(GPIOA ODR, RX snapshot, TIM2 count, USART1 TX bytes)`.
/// `None` means the test was skipped (missing toolchain or pack).
fn run_stm32_firmware(
    board: impl FnOnce() -> board::BoardMemory,
) -> Option<(u32, u32, u32, Vec<u8>)> {
    run_stm32_firmware_with_includes(
        board,
        STM32_F103_FIRMWARE,
        &[
            "../packs/Keil.STM32F1xx_DFP/Device/Include",
            "../packs/STM32F4xx_CMSIS/CMSIS/Core/Include",
        ],
    )
}

/// Compile `firmware` with `includes` as extra `-I` paths, boot it on `board`,
/// inject a received byte, and return `(GPIOA ODR, RX snapshot, TIM2 count,
/// USART1 TX bytes)`. `None` means the test was skipped (missing toolchain or
/// pack).
fn run_stm32_firmware_with_includes(
    board: impl FnOnce() -> board::BoardMemory,
    firmware: &str,
    includes: &[&str],
) -> Option<(u32, u32, u32, Vec<u8>)> {
    let mut include_paths = Vec::new();
    for rel in includes {
        let include = PathBuf::from(env!("CARGO_MANIFEST_DIR")).join(rel);
        if !include.is_dir() {
            eprintln!(
                "skipping stm32 test: pack include dir {} not found",
                include.display()
            );
            return None;
        }
        include_paths.push(
            include
                .to_str()
                .expect("pack include path is not UTF-8")
                .to_owned(),
        );
    }
    let include_refs: Vec<&str> = include_paths.iter().map(String::as_str).collect();
    let (code, symbols) = match build_firmware_with_includes(firmware, &include_refs) {
        Ok(image) => image,
        Err(why) => {
            eprintln!("skipping stm32 test: {why}");
            return None;
        }
    };
    let entry = *symbols.get("reset").expect("no reset symbol");
    let irq = *symbols
        .get("USART1_IRQHandler")
        .expect("no USART1_IRQHandler symbol");
    assert!(!code.is_empty(), "compiled .text must not be empty");

    let mut m = Machine::new(board());
    m.load_image(&load_flat(CODE_BASE, &code));
    {
        let mem = m.core.mem();
        mem.write_word(FLASH, INIT_SP).unwrap();
        mem.write_word(FLASH + 4, (CODE_BASE + entry) | 1).unwrap();
        // Vector 53 = USART1 IRQ 37 at FLASH + 53 * 4.
        mem.write_word(FLASH + 53 * 4, (CODE_BASE + irq) | 1)
            .unwrap();
    }
    m.reset().expect("reset from vector table");
    // Host stimulus: one byte arrives on the USART1 RX line while the
    // firmware boots. (The GPIO/EXTI devices consume the same channel.)
    for device in m.core.mem().devices_mut() {
        device.drive_inputs(0x5A);
    }
    let err = m.run(200_000);
    assert_eq!(err, Err(HaltCause::NonThumbTarget));
    // GPIO: PA0 was driven high through BSRR and read back on ODR.
    let odr = m.core.mem().read_word(board::RAM).unwrap();
    // USART1: the interrupt handler latched the received byte.
    let rx = m.core.mem().read_word(board::RAM + 4).unwrap();
    // TIM2: the free-running counter advanced past zero.
    let tim_cnt = m.core.mem().read_word(board::RAM + 8).unwrap();
    // USART1 TX: the transmitted line reached the host channel.
    let mut tx = Vec::new();
    for device in m.core.mem().devices_mut() {
        tx.extend(device.drain_output());
    }
    Some((odr, rx, tim_cnt, tx))
}

/// On the STM32F103 board, firmware compiled against the real device header
/// enables clocks, drives GPIO, transmits over `USART1`, receives a byte
/// through its IRQ, and lets `TIM2` free-run — all through real registers.
#[test]
fn stm32f103_firmware_uses_real_peripherals() {
    let Some((odr, rx, tim_cnt, tx)) = run_stm32_firmware(board::stm32f103) else {
        return; // skipped
    };
    assert_eq!(odr, 0x1);
    assert_eq!(rx, 0x5A);
    assert!(tim_cnt > 0, "TIM2 never counted: {tim_cnt}");
    assert_eq!(tx, b"ok!\n");
}

