/// Real CMSIS-style firmware against the STM32F1 DMA controller: a
/// memory-to-memory copy through `DMA1` channel 1, driven to completion by the
/// transfer-complete interrupt (IRQ 11, exception 27). The result snapshot is
/// `1` only if the 16-word copy landed, `CNDTR1` reads zero, `EN` self-cleared,
/// and the handler ran.
const STM32_F103_DMA_FIRMWARE: &str = r#"
#define STM32F10X_HD
#include "stm32f10x.h"

#define SRC_ADDR 0x20000100u
#define DST_ADDR 0x20000200u
#define DONE_ADDR 0x20000300u
#define RESULT_ADDR 0x20000304u
#define DONE_WORD (*(volatile unsigned *)DONE_ADDR)

void DMA1_Channel1_IRQHandler(void) {
    if (DMA1->ISR & DMA_ISR_TCIF1) {
        DONE_WORD = 1;
        DMA1->IFCR = DMA_IFCR_CTCIF1;
    }
}

void reset(void) {
    /* 1. Fill the source buffer with a 32-bit pattern. */
    volatile unsigned *src = (volatile unsigned *)SRC_ADDR;
    for (unsigned i = 0; i < 16; ++i) src[i] = 0xDEAD0000u | i;

    /* 2. Clear the destination. */
    volatile unsigned *dst = (volatile unsigned *)DST_ADDR;
    for (unsigned i = 0; i < 16; ++i) dst[i] = 0;

    /* 3. Arm the DMA1 channel-1 IRQ (IRQ 11, exception 27). */
    NVIC->ISER[0] = 1u << DMA1_Channel1_IRQn;

    /* 4. Memory-to-memory copy of 16 words, both sides incrementing. */
    DMA1_Channel1->CPAR = SRC_ADDR;
    DMA1_Channel1->CMAR = DST_ADDR;
    DMA1_Channel1->CNDTR = 16;
    DMA1_Channel1->CCR = DMA_CCR1_MEM2MEM | DMA_CCR1_PINC | DMA_CCR1_MINC |
                         DMA_CCR1_PSIZE_1 | DMA_CCR1_MSIZE_1 |
                         DMA_CCR1_TCIE | DMA_CCR1_EN;

    /* 5. Wait for the transfer-complete interrupt. */
    while (!DONE_WORD) { }

    /* 6. Verify the copy and the post-transfer register state. */
    unsigned ok = 1;
    for (unsigned i = 0; i < 16; ++i) {
        if (dst[i] != (0xDEAD0000u | i)) { ok = 0; break; }
        if (src[i] != (0xDEAD0000u | i)) { ok = 0; break; }
    }
    if (DMA1_Channel1->CNDTR != 0) ok = 0;
    if (DMA1_Channel1->CCR & DMA_CCR1_EN) ok = 0;

    *(volatile unsigned *)RESULT_ADDR = ok;
    __asm__ volatile("bkpt #0");
}
"#;

/// On the STM32F103 board, CMSIS firmware copies 16 words with `DMA1` channel
/// 1 in memory-to-memory mode, completes the transfer through the IRQ, and
/// verifies the result.
#[test]
fn stm32f103_dma_transfers_memory_to_memory() {
    let Some((code, symbols)) = build_f1_dma_firmware(STM32_F103_DMA_FIRMWARE) else {
        return; // skipped
    };
    let entry = *symbols.get("reset").expect("no reset symbol");
    let irq = *symbols
        .get("DMA1_Channel1_IRQHandler")
        .expect("no DMA1_Channel1_IRQHandler symbol");
    assert!(!code.is_empty(), "compiled .text must not be empty");

    let mut m = Machine::new(board::stm32f103());
    m.load_image(&load_flat(CODE_BASE, &code));
    {
        let mem = m.core.mem();
        mem.write_word(FLASH, INIT_SP).unwrap();
        mem.write_word(FLASH + 4, (CODE_BASE + entry) | 1).unwrap();
        // Vector 27 = DMA1_Channel1 IRQ 11 at FLASH + 27 * 4.
        mem.write_word(FLASH + 27 * 4, (CODE_BASE + irq) | 1)
            .unwrap();
    }
    m.reset().expect("reset from vector table");
    let err = m.run(100_000);
    assert_eq!(err, Err(HaltCause::NonThumbTarget));
    assert_eq!(
        m.core.mem().read_word(0x2000_0300).unwrap(),
        1,
        "the transfer-complete IRQ fired"
    );
    assert_eq!(
        m.core.mem().read_word(0x2000_0304).unwrap(),
        1,
        "the memory-to-memory copy was verified"
    );
}

/// Compile `firmware` against the STM32F1 device header, returning the flat
/// `.text` and symbol map, or `None` if the toolchain or pack is missing.
fn build_f1_dma_firmware(
    firmware: &str,
) -> Option<(Vec<u8>, std::collections::HashMap<String, u32>)> {
    let includes = [
        "../packs/Keil.STM32F1xx_DFP/Device/Include",
        "../packs/STM32F4xx_CMSIS/CMSIS/Core/Include",
    ];
    let mut include_paths = Vec::new();
    for rel in includes {
        let include = PathBuf::from(env!("CARGO_MANIFEST_DIR")).join(rel);
        if !include.is_dir() {
            eprintln!(
                "skipping dma test: pack include dir {} not found",
                include.display()
            );
            return None;
        }
        include_paths.push(
            include
                .to_str()
                .expect("pack include path is not UTF-8")
                .to_owned(),
        );
    }
    let include_refs: Vec<&str> = include_paths.iter().map(String::as_str).collect();
    match build_firmware_with_includes(firmware, &include_refs) {
        Ok(image) => Some(image),
        Err(why) => {
            eprintln!("skipping dma test: {why}");
            None
        }
    }
}

/// Real CMSIS-style firmware against the STM32F1 DMA request path: `USART1`
/// transmits a byte string over DMA1 channel 4 (memory→peripheral), driven to
/// completion by the channel-4 transfer-complete interrupt (IRQ 14, exception
/// 30). `RESULT` is `1` only if `CNDTR` read zero, `EN` self-cleared, and the
/// handler ran — and the host side asserts the transmitted bytes matched.
const STM32_F103_DMA_TX_FIRMWARE: &str = r#"
#define STM32F10X_HD
#include "stm32f10x.h"

#define TX_ADDR 0x20000100u
#define DONE_ADDR 0x20000300u
#define RESULT_ADDR 0x20000304u
#define DONE_WORD (*(volatile unsigned *)DONE_ADDR)

void DMA1_Channel4_IRQHandler(void) {
    if (DMA1->ISR & DMA_ISR_TCIF4) {
        DONE_WORD = 1;
        DMA1->IFCR = DMA_IFCR_CTCIF4;
    }
}

void reset(void) {
    /* 1. Fill the transmit buffer. */
    volatile unsigned char *tx = (volatile unsigned char *)TX_ADDR;
    const unsigned char msg[] = "dma ok!\n";
    unsigned len = 0;
    while (msg[len] != 0) { tx[len] = msg[len]; ++len; }

    /* 2. Enable clocks (gating is not enforced; kept for realism). */
    RCC->APB2ENR |= RCC_APB2ENR_IOPAEN | RCC_APB2ENR_USART1EN;

    /* 3. USART1 at 8 MHz HSI / 9600 baud, transmitter on. */
    USART1->BRR = 0x341;
    USART1->CR1 = USART_CR1_UE | USART_CR1_TE;

    /* 4. Arm the DMA1 channel-4 IRQ (IRQ 14, exception 30). */
    NVIC->ISER[0] = 1u << DMA1_Channel4_IRQn;

    /* 5. DMA1 channel 4: memory -> USART1 DR, byte units, memory increment.
          The USART1 TX request line feeds the channel every cycle. */
    DMA1_Channel4->CPAR = (unsigned)&USART1->DR;
    DMA1_Channel4->CMAR = TX_ADDR;
    DMA1_Channel4->CNDTR = len;
    DMA1_Channel4->CCR = DMA_CCR4_MINC | DMA_CCR4_TCIE | DMA_CCR4_EN;

    /* 6. Wait for the transfer-complete interrupt. */
    while (!DONE_WORD) { }

    /* 7. Verify the channel completed cleanly. */
    unsigned ok = 1;
    if (DMA1_Channel4->CNDTR != 0) ok = 0;
    if (DMA1_Channel4->CCR & DMA_CCR4_EN) ok = 0;
    *(volatile unsigned *)RESULT_ADDR = ok;
    __asm__ volatile("bkpt #0");
}
"#;

/// On the STM32F103 board, `USART1` TX drives `DMA1` channel 4 over the
/// peripheral-request line: the string reaches the host channel and the
/// channel-4 IRQ fires on completion.
#[test]
fn stm32f103_dma_transmits_usart1_via_peripheral_request() {
    let Some((code, symbols)) = build_f1_dma_firmware(STM32_F103_DMA_TX_FIRMWARE) else {
        return; // skipped
    };
    let entry = *symbols.get("reset").expect("no reset symbol");
    let irq = *symbols
        .get("DMA1_Channel4_IRQHandler")
        .expect("no DMA1_Channel4_IRQHandler symbol");
    assert!(!code.is_empty(), "compiled .text must not be empty");

    let mut m = Machine::new(board::stm32f103());
    m.load_image(&load_flat(CODE_BASE, &code));
    {
        let mem = m.core.mem();
        mem.write_word(FLASH, INIT_SP).unwrap();
        mem.write_word(FLASH + 4, (CODE_BASE + entry) | 1).unwrap();
        // Vector 30 = DMA1_Channel4 IRQ 14 at FLASH + 30 * 4.
        mem.write_word(FLASH + 30 * 4, (CODE_BASE + irq) | 1)
            .unwrap();
    }
    m.reset().expect("reset from vector table");
    let err = m.run(100_000);
    assert_eq!(err, Err(HaltCause::NonThumbTarget));
    let mut tx = Vec::new();
    for device in m.core.mem().devices_mut() {
        tx.extend(device.drain_output());
    }
    assert_eq!(tx, b"dma ok!\n", "the DMA-fed USART TX reached the host");
    assert_eq!(
        m.core.mem().read_word(0x2000_0304).unwrap(),
        1,
        "the peripheral-request transmit was verified"
    );
}

/// Real CMSIS-style firmware against the STM32F1 DMA request path in the
/// receive direction: `USART1` RX fills a buffer through DMA1 channel 5
/// (peripheral→memory), with the channel-5 transfer-complete interrupt (IRQ
/// 15, exception 31) signaling completion. The host injects four bytes one at
/// a time; `RESULT` is `1` only if they landed in order and the channel
/// completed cleanly.
const STM32_F103_DMA_RX_FIRMWARE: &str = r#"
#define STM32F10X_HD
#include "stm32f10x.h"

#define RX_ADDR 0x20000100u
#define DONE_ADDR 0x20000300u
#define RESULT_ADDR 0x20000304u
#define DONE_WORD (*(volatile unsigned *)DONE_ADDR)

void DMA1_Channel5_IRQHandler(void) {
    if (DMA1->ISR & DMA_ISR_TCIF5) {
        DONE_WORD = 1;
        DMA1->IFCR = DMA_IFCR_CTCIF5;
    }
}

void reset(void) {
    RCC->APB2ENR |= RCC_APB2ENR_IOPAEN | RCC_APB2ENR_USART1EN;

    USART1->BRR = 0x341;
    USART1->CR1 = USART_CR1_UE | USART_CR1_RE;

    NVIC->ISER[0] = 1u << DMA1_Channel5_IRQn;

    /* USART1 -> DMA1 channel 5, byte units, memory increment. */
    DMA1_Channel5->CPAR = (unsigned)&USART1->DR;
    DMA1_Channel5->CMAR = RX_ADDR;
    DMA1_Channel5->CNDTR = 4;
    DMA1_Channel5->CCR = DMA_CCR5_MINC | DMA_CCR5_TCIE | DMA_CCR5_EN;

    while (!DONE_WORD) { }

    volatile unsigned char *rx = (volatile unsigned char *)RX_ADDR;
    unsigned ok = (rx[0] == 'd') & (rx[1] == 'm') & (rx[2] == 'a') & (rx[3] == '\n');
    if (DMA1_Channel5->CNDTR != 0) ok = 0;
    if (DMA1_Channel5->CCR & DMA_CCR5_EN) ok = 0;
    *(volatile unsigned *)RESULT_ADDR = ok;
    __asm__ volatile("bkpt #0");
}
"#;

/// On the STM32F103 board, host-injected USART1 RX bytes are absorbed by `DMA1`
/// channel 5 over the peripheral-request line and verified by the firmware.
#[test]
fn stm32f103_dma_receives_usart1_via_peripheral_request() {
    let Some((code, symbols)) = build_f1_dma_firmware(STM32_F103_DMA_RX_FIRMWARE) else {
        return; // skipped
    };
    let entry = *symbols.get("reset").expect("no reset symbol");
    let irq = *symbols
        .get("DMA1_Channel5_IRQHandler")
        .expect("no DMA1_Channel5_IRQHandler symbol");
    assert!(!code.is_empty(), "compiled .text must not be empty");

    let mut m = Machine::new(board::stm32f103());
    m.load_image(&load_flat(CODE_BASE, &code));
    {
        let mem = m.core.mem();
        mem.write_word(FLASH, INIT_SP).unwrap();
        mem.write_word(FLASH + 4, (CODE_BASE + entry) | 1).unwrap();
        // Vector 31 = DMA1_Channel5 IRQ 15 at FLASH + 31 * 4.
        mem.write_word(FLASH + 31 * 4, (CODE_BASE + irq) | 1)
            .unwrap();
    }
    m.reset().expect("reset from vector table");
    // Inject the four bytes one at a time, giving the DMA a few cycles to
    // absorb each one before the next arrives on the wire. The final byte
    // completes the transfer and halts the firmware.
    for byte in b"dma\n" {
        for device in m.core.mem().devices_mut() {
            device.drive_inputs(u32::from(*byte));
        }
        if m.run(100) == Err(HaltCause::NonThumbTarget) {
            break;
        }
    }
    let err = m.run(100_000);
    assert_eq!(err, Err(HaltCause::NonThumbTarget));
    assert_eq!(
        m.core.mem().read_word(0x2000_0304).unwrap(),
        1,
        "the DMA-fed USART RX was verified"
    );
}

/// ARMv7-M firmware that enables `SHCSR.USGFAULTENA`, trips an undefined
/// instruction, and verifies the distinct `UsageFault` handler ran with the
/// `UNDEFINSTR` cause and no `FORCED` escalation.
///
/// The handler clears `USGFAULTENA` before its trailing `bkpt` so the debug
/// trap faults straight into (disabled) `HardFault`; with no `HardFault` vector
/// written the core halts with `NonThumbTarget`, leaving the `ENTRY`/`CAUSE`
/// snapshots intact.
const USAGE_FAULT_FIRMWARE: &str = r#"
#define SHCSR 0xE000ED24u
#define CFSR  0xE000ED28u
#define HFSR  0xE000ED2Cu
#define ENTRY 0x20000000u
#define CAUSE 0x20000004u
#define HFRS  0x20000008u

void UsageFault_Handler(void) {
    *(volatile unsigned *)ENTRY = 6;
    *(volatile unsigned *)CAUSE = *(volatile unsigned *)CFSR;
    *(volatile unsigned *)HFRS = *(volatile unsigned *)HFSR;
    *(volatile unsigned *)SHCSR &= ~0x40000u; /* stop re-faulting on the trap */
    __asm__ volatile("bkpt #0");              /* HardFault (disabled) -> halt */
}

void reset(void) {
    *(volatile unsigned *)SHCSR |= 0x40000u; /* USGFAULTENA */
    __asm__ volatile("udf #0");              /* -> distinct UsageFault */
}
"#;

/// On the STM32F103 board (ARMv7-M core), a distinct `UsageFault` exception is
/// taken for an undefined instruction when `USGFAULTENA` is set, and the
/// `UNDEFINSTR` cause is visible in `CFSR` without a `FORCED` escalation.
#[test]
fn usage_fault_is_a_distinct_exception_for_real_firmware() {
    let (code, symbols) = match build_firmware_v7m_with_includes(USAGE_FAULT_FIRMWARE, &[]) {
        Ok(image) => image,
        Err(why) => {
            eprintln!("skipping usage-fault test: {why}");
            return;
        }
    };
    let entry = *symbols.get("reset").expect("no reset symbol");
    let uf = *symbols
        .get("UsageFault_Handler")
        .expect("no UsageFault_Handler symbol");
    assert!(!code.is_empty(), "compiled .text must not be empty");

    let mut m = Machine::armv7m(board::stm32f103());
    m.load_image(&load_flat(CODE_BASE, &code));
    {
        let mem = m.core.mem();
        mem.write_word(FLASH, INIT_SP).unwrap();
        mem.write_word(FLASH + 4, (CODE_BASE + entry) | 1).unwrap();
        // UsageFault vector 6 at FLASH + 24; HardFault vector left unset so
        // the handler's `bkpt` escalates to HardFault -> vector 0 -> halt.
        mem.write_word(FLASH + 6 * 4, (CODE_BASE + uf) | 1).unwrap();
    }
    m.reset().expect("reset from vector table");
    let err = m.run(100_000);
    assert_eq!(err, Err(HaltCause::NonThumbTarget));
    assert_eq!(
        m.core.mem().read_word(0x2000_0000).unwrap(),
        6,
        "the UsageFault handler ran, not HardFault"
    );
    // UNDEFINSTR (UFSR bit 0 -> CFSR bit 16), no FORCED in HFSR.
    assert_eq!(m.core.mem().read_word(0x2000_0004).unwrap(), 0x0001_0000);
    assert_eq!(m.core.mem().read_word(0x2000_0008).unwrap(), 0);
}

/// ARMv7-M firmware that leaves `CPACR` at reset (FPU denied) and executes a
/// VFP instruction: the access is rejected with a `NOCP` `UsageFault`.
const NOCP_FIRMWARE: &str = r#"
#define SHCSR 0xE000ED24u
#define CFSR  0xE000ED28u
#define ENTRY 0x20000000u
#define CAUSE 0x20000004u

void UsageFault_Handler(void) {
    *(volatile unsigned *)ENTRY = 6;
    *(volatile unsigned *)CAUSE = *(volatile unsigned *)CFSR;
    *(volatile unsigned *)SHCSR &= ~0x40000u; /* stop re-faulting on the trap */
    __asm__ volatile("bkpt #0");              /* HardFault (disabled) -> halt */
}

void reset(void) {
    *(volatile unsigned *)SHCSR |= 0x40000u; /* USGFAULTENA */
    __asm__ volatile("vmov s0, r0");         /* CPACR denies: -> NOCP */
}
"#;

/// A VFP instruction with `CPACR` at zero (the reset state, denying FPU
/// access) raises a `NOCP` `UsageFault` instead of executing.
#[test]
fn cpacr_denies_vfp_with_nocp_usage_fault() {
    let (code, symbols) = match build_firmware_v7m_fp_with_includes(NOCP_FIRMWARE, &[]) {
        Ok(image) => image,
        Err(why) => {
            eprintln!("skipping nocp test: {why}");
            return;
        }
    };
    let entry = *symbols.get("reset").expect("no reset symbol");
    let uf = *symbols
        .get("UsageFault_Handler")
        .expect("no UsageFault_Handler symbol");

    let mut m = Machine::armv7m(board::stm32f103());
    m.load_image(&load_flat(CODE_BASE, &code));
    {
        let mem = m.core.mem();
        mem.write_word(FLASH, INIT_SP).unwrap();
        mem.write_word(FLASH + 4, (CODE_BASE + entry) | 1).unwrap();
        // UsageFault vector 6 at FLASH + 24; HardFault vector left unset so
        // the handler's `bkpt` escalates to HardFault -> vector 0 -> halt.
        mem.write_word(FLASH + 6 * 4, (CODE_BASE + uf) | 1).unwrap();
    }
    m.reset().expect("reset from vector table");
    let err = m.run(100_000);
    assert_eq!(err, Err(HaltCause::NonThumbTarget));
    assert_eq!(
        m.core.mem().read_word(0x2000_0000).unwrap(),
        6,
        "the UsageFault handler ran, not HardFault"
    );
    // NOCP (UFSR bit 1 -> CFSR bit 17).
    assert_eq!(m.core.mem().read_word(0x2000_0004).unwrap(), 0x0002_0000);
}

/// ARMv7-M firmware that enables the MPU with a flash region (covering the
/// code) and a 32 KiB SRAM region, then reads from an address outside every
/// region. The access is denied and escalates to `HardFault`, whose handler
/// records its entry in SRAM and `bkpt`s; the trap's `UsageFault` folds into
/// the already-active `HardFault` and locks the core up, leaving the fault
/// snapshot intact.
const MPU_FAULT_FIRMWARE: &str = r#"
#define MPU_CTRL 0xE000ED94u
#define MPU_RNR  0xE000ED98u
#define MPU_RBAR 0xE000ED9Cu
#define MPU_RASR 0xE000EDA0u
#define ENTRY    0x20000000u

void HardFault_Handler(void) {
    *(volatile unsigned *)ENTRY = 3;
    __asm__ volatile("bkpt #0"); /* UsageFault -> active HardFault -> lockup */
}

void reset(void) {
    /* region 0: 8 KiB of flash, rw/rw (fetch + any literal reads). */
    *(volatile unsigned *)MPU_RNR = 0;
    *(volatile unsigned *)MPU_RBAR = 0x00000000u;
    *(volatile unsigned *)MPU_RASR = 0x03000019u;
    /* region 1: 32 KiB of SRAM, rw/rw (stack, globals, handler record). */
    *(volatile unsigned *)MPU_RNR = 1;
    *(volatile unsigned *)MPU_RBAR = 0x20000000u;
    *(volatile unsigned *)MPU_RASR = 0x0300001Du;
    *(volatile unsigned *)MPU_CTRL = 1; /* ENABLE, no PRIVDEFENA */
    volatile unsigned bad = *(volatile unsigned *)0x20008000u; /* unmapped */
    (void)bad;
}
"#;

/// A read from an address outside every MPU region raises a `DACCVIOL`
/// escalated to `HardFault`, with the denied address latched in `MMFAR` and
/// the escalation recorded as `HFSR.FORCED`.
#[test]
fn mpu_denies_unmapped_access_for_real_firmware() {
    let (code, symbols) = match build_firmware_v7m_with_includes(MPU_FAULT_FIRMWARE, &[]) {
        Ok(image) => image,
        Err(why) => {
            eprintln!("skipping mpu test: {why}");
            return;
        }
    };
    let entry = *symbols.get("reset").expect("no reset symbol");
    let hf = *symbols
        .get("HardFault_Handler")
        .expect("no HardFault_Handler symbol");
    assert!(!code.is_empty(), "compiled .text must not be empty");

    let mut m = Machine::armv7m(board::stm32f103());
    m.load_image(&load_flat(CODE_BASE, &code));
    {
        let mem = m.core.mem();
        mem.write_word(FLASH, INIT_SP).unwrap();
        mem.write_word(FLASH + 4, (CODE_BASE + entry) | 1).unwrap();
        mem.write_word(FLASH + 3 * 4, (CODE_BASE + hf) | 1).unwrap();
    }
    m.reset().expect("reset from vector table");
    let err = m.run(100_000);
    // The handler's bkpt folds into the active HardFault and locks the core.
    assert_eq!(err, Err(HaltCause::UnhandledException));
    assert_eq!(
        m.core.mem().read_word(0x2000_0000).unwrap(),
        3,
        "the HardFault handler ran"
    );
    // MMFSR: DACCVIOL|MMARVALID; MMFAR = the denied address; HFSR: FORCED.
    assert_eq!(m.core.mem().read_word(0xE000_ED28).unwrap() & 0xFF, 0x82);
    assert_eq!(m.core.mem().read_word(0xE000_ED2C).unwrap(), 0x4000_0000);
    assert_eq!(m.core.mem().read_word(0xE000_ED34).unwrap(), 0x2000_8000);
}

/// Real CMSIS firmware against the `bxCAN` controller on the connectivity
/// line: `STM32F10X_CL` exposes `CAN1` and the `USB_LP_CAN1_RX0` interrupt.
/// The firmware takes the controller through its init handshake, arms the
/// FIFO-0 message-pending interrupt, latches an incoming frame's identifier,
/// DLC and first byte in the handler, then transmits a frame of its own and
/// polls the mailbox empty bit.
const STM32_F107_CAN_FIRMWARE: &str = r#"
#define STM32F10X_CL
#include "stm32f10x.h"

#define RX_ID   (*(volatile unsigned *)0x20000000u)
#define RX_DLC  (*(volatile unsigned *)0x20000004u)
#define RX_D0   (*(volatile unsigned *)0x20000008u)
#define TX_DONE (*(volatile unsigned *)0x2000000Cu)

void USB_LP_CAN1_RX0_IRQHandler(void) {
    if (CAN1->RF0R & CAN_RF0R_FMP0) {
        RX_ID  = CAN1->sFIFOMailBox[0].RIR & 0xFFFFu;
        RX_DLC = CAN1->sFIFOMailBox[0].RDTR & CAN_TDT0R_DLC;
        RX_D0  = CAN1->sFIFOMailBox[0].RDLR & 0xFFu;
        CAN1->RF0R = CAN_RF0R_RFOM0;    /* release the FIFO slot */
    }
}

void reset(void) {
    RCC->APB1ENR |= RCC_APB1ENR_CAN1EN;
    CAN1->MCR = CAN_MCR_INRQ;           /* enter initialization mode */
    while (!(CAN1->MSR & CAN_MSR_INAK)) { }
    CAN1->BTR = (4u - 1u) | (8u << 16) | (1u << 20);   /* BRP=4, TS1=8, TS2=1 */
    CAN1->MCR = 0u;                     /* leave initialization mode */
    while (CAN1->MSR & CAN_MSR_INAK) { }
    CAN1->IER = CAN_IER_FMPIE0;
    NVIC->ISER[0] = 1u << USB_LP_CAN1_RX0_IRQn;
    while (!RX_D0) { }                  /* wait for the incoming frame */
    CAN1->sTxMailBox[0].TDLR = 0x5Au;
    CAN1->sTxMailBox[0].TDTR = 1u;
    CAN1->sTxMailBox[0].TIR = (0x7E5u << 21) | CAN_TI0R_TXRQ;
    while (!(CAN1->TSR & CAN_TSR_TME0)) { }    /* wait for the mailbox to empty */
    TX_DONE = 1u;
    __asm__ volatile("bkpt #0");
}
"#;

/// Compile `STM32_F107_CAN_FIRMWARE` against the F1 pack headers, run it on
/// the F107 board, and return the four RAM snapshots plus the transmitted
/// frame. `None` means the toolchain or pack was unavailable.
fn run_can_firmware() -> Option<(u32, u32, u32, u32, Vec<u8>)> {
    let includes = [
        "../packs/Keil.STM32F1xx_DFP/Device/Include",
        "../packs/STM32F4xx_CMSIS/CMSIS/Core/Include",
    ];
    let mut include_paths = Vec::new();
    for rel in includes {
        let include = PathBuf::from(env!("CARGO_MANIFEST_DIR")).join(rel);
        if !include.is_dir() {
            eprintln!(
                "skipping can test: pack include dir {} not found",
                include.display()
            );
            return None;
        }
        include_paths.push(
            include
                .to_str()
                .expect("pack include path is not UTF-8")
                .to_owned(),
        );
    }
    let include_refs: Vec<&str> = include_paths.iter().map(String::as_str).collect();
    let (code, symbols) = match build_firmware_with_includes(STM32_F107_CAN_FIRMWARE, &include_refs)
    {
        Ok(image) => image,
        Err(why) => {
            eprintln!("skipping can test: {why}");
            return None;
        }
    };
    let entry = *symbols.get("reset").expect("no reset symbol");
    let irq = *symbols
        .get("USB_LP_CAN1_RX0_IRQHandler")
        .expect("no CAN1_RX0 handler symbol");
    assert!(!code.is_empty(), "compiled .text must not be empty");

    let mut m = Machine::new(board::stm32f107());
    m.load_image(&load_flat(CODE_BASE, &code));
    {
        let mem = m.core.mem();
        mem.write_word(FLASH, INIT_SP).unwrap();
        mem.write_word(FLASH + 4, (CODE_BASE + entry) | 1).unwrap();
        // Vector 36 = CAN1_RX0 IRQ 20 at FLASH + 36 * 4.
        mem.write_word(FLASH + 36 * 4, (CODE_BASE + irq) | 1)
            .unwrap();
    }
    m.reset().expect("reset from vector table");
    // Host stimulus: a standard frame, id 0x123, DLC 3, bytes AA BB CC.
    let mut frame = [0u8; 16];
    frame[0..4].copy_from_slice(&0x123u32.to_le_bytes());
    frame[4] = 3;
    frame[8..11].copy_from_slice(&[0xAA, 0xBB, 0xCC]);
    for byte in frame {
        for device in m.core.mem().devices_mut() {
            device.drive_inputs(u32::from(byte));
        }
    }
    let err = m.run(200_000);
    assert_eq!(err, Err(HaltCause::NonThumbTarget));
    let rx_id = m.core.mem().read_word(board::RAM).unwrap();
    let rx_dlc = m.core.mem().read_word(board::RAM + 4).unwrap();
    let rx_d0 = m.core.mem().read_word(board::RAM + 8).unwrap();
    let tx_done = m.core.mem().read_word(board::RAM + 12).unwrap();
    let mut tx = Vec::new();
    for device in m.core.mem().devices_mut() {
        tx.extend(device.drain_output());
    }
    Some((rx_id, rx_dlc, rx_d0, tx_done, tx))
}

/// On the STM32F107 board, CMSIS firmware talks `bxCAN`: the FIFO-0 message
/// pending interrupt wakes the handler for the injected frame, and the
/// transmitted frame reaches the host channel with its identifier intact.
#[test]
fn stm32f107_firmware_talks_can1() {
    let Some((rx_id, rx_dlc, rx_d0, tx_done, tx)) = run_can_firmware() else {
        return; // skipped
    };
    assert_eq!(rx_id, 0x123, "received identifier");
    assert_eq!(rx_dlc, 3, "received DLC");
    assert_eq!(rx_d0, 0xAA, "first received byte");
    assert_eq!(tx_done, 1, "the transmit completed");
    // The transmitted frame is one 16-byte host descriptor: id 0x7E5,
    // DLC 1, byte 0x5A.
    assert_eq!(tx.len(), 16, "one transmitted frame drained");
    let mut ti = [0u8; 4];
    ti.copy_from_slice(&tx[0..4]);
    let ti = u32::from_le_bytes(ti) & !0x1; // clear the TXRQ latch
    assert_eq!(ti >> 21, 0x7E5, "transmitted identifier");
    assert_eq!(tx[4], 1, "transmitted DLC");
    assert_eq!(tx[8], 0x5A, "transmitted byte");
}

/// CMSIS firmware for the STM32F107 `OTG_FS` controller. The F1 headers expose
/// no OTG register structs, so the controller is driven through raw volatile
/// pointers at `0x50000000` (GLOBAL) / `0x50000800` (DEVICE) / `0x50001000`
/// (FIFO 0). The core soft reset is followed by the device-mode setup, then
/// the ISR serves the enumerated bus: a USBRST clears the endpoint flags, the
/// RX FIFO pops the 8-byte SETUP, the STUP latch arms the IN reply, and the
/// 18-byte device descriptor is pushed through endpoint 0.
const STM32_F107_USB_FIRMWARE: &str = r#"
#define STM32F10X_CL
#include "stm32f10x.h"

#define ENUM_DONE   (*(volatile unsigned *)0x20000000u)
#define IN_READY    (*(volatile unsigned *)0x20000004u)
#define XFR_DONE    (*(volatile unsigned *)0x20000008u)
#define DESC_LEN    (*(volatile unsigned *)0x2000000Cu)
#define CONFIGURED  (*(volatile unsigned *)0x20000010u)

#define GAHBCFG   (*(volatile unsigned *)0x50000008u)
#define GUSBCFG   (*(volatile unsigned *)0x5000000Cu)
#define GRSTCTL   (*(volatile unsigned *)0x50000010u)
#define GINTSTS   (*(volatile unsigned *)0x50000014u)
#define GINTMSK   (*(volatile unsigned *)0x50000018u)
#define GRXSTSR   (*(volatile unsigned *)0x5000001Cu)
#define DIEPMSK   (*(volatile unsigned *)0x50000810u)
#define DOEPMSK   (*(volatile unsigned *)0x50000814u)
#define DAINTMSK  (*(volatile unsigned *)0x5000081Cu)
#define DIEPCTL0  (*(volatile unsigned *)0x50000900u)
#define DIEPINT0  (*(volatile unsigned *)0x50000908u)
#define DIEPTSIZ0 (*(volatile unsigned *)0x50000910u)
#define DOEPCTL0  (*(volatile unsigned *)0x50000B00u)
#define DOEPINT0  (*(volatile unsigned *)0x50000B08u)
#define DOEPTSIZ0 (*(volatile unsigned *)0x50000B10u)
#define FS_FIFO0  ((volatile unsigned *)0x50001000u)

void OTG_FS_IRQHandler(void) {
    unsigned g = GINTSTS;
    if (g & (1u << 12)) {                    /* USBRST */
        DIEPINT0 = 0xFFFFFFFFu;
        DOEPINT0 = 0xFFFFFFFFu;
    }
    if (g & (1u << 13)) {                    /* ENUMDNE */
        ENUM_DONE = 1u;
    }
    if (g & (1u << 4)) {                     /* RXFLVL */
        unsigned st = GRXSTSR;
        if (((st >> 17) & 0xFu) == 2u) {     /* PKTSTS: SETUP */
            (void)FS_FIFO0[0];
            (void)FS_FIFO0[1];
            DOEPTSIZ0 = (1u << 29) | (1u << 19) | 8u;
            DOEPCTL0 |= 0x80000000u;         /* EPENA */
        }
    }
    if (g & (1u << 19)) {                    /* OEPINT */
        if (DOEPINT0 & (1u << 3)) {          /* STUP */
            IN_READY = 1u;
        }
        DOEPINT0 = 0xFFFFFFFFu;
    }
    if (g & (1u << 18)) {                    /* IEPINT */
        if (DIEPINT0 & 1u) {                 /* XFRC */
            XFR_DONE = 1u;
        }
        DIEPINT0 = 0xFFFFFFFFu;
    }
    GINTSTS = g;
}

void reset(void) {
    RCC->AHBENR |= RCC_AHBENR_OTGFSEN;
    GUSBCFG = 1u << 30;                      /* FDMOD: device mode */
    GRSTCTL = 1u;                            /* CSRST: core soft reset */
    while (GRSTCTL & 1u) { }
    GUSBCFG = 1u << 30;                      /* FDMOD again after the reset */
    GAHBCFG = 1u;                            /* GINT: global interrupt enable */
    GINTMSK = (1u << 12) | (1u << 13) | (1u << 4) | (1u << 18) | (1u << 19);
    DAINTMSK = (1u << 0) | (1u << 16);
    DIEPMSK = 1u;                            /* XFRCM */
    DOEPMSK = (1u << 0) | (1u << 3);         /* XFRCM | STUPM */
    NVIC->ISER[2] = 1u << (OTG_FS_IRQn - 64u);
    CONFIGURED = 1u;

    while (!IN_READY) { }
    FS_FIFO0[0] = 0x02000112u;
    FS_FIFO0[1] = 0x40000000u;
    FS_FIFO0[2] = 0x57100483u;
    FS_FIFO0[3] = 0x02010100u;
    FS_FIFO0[4] = 0x00000100u;
    DIEPTSIZ0 = (1u << 19) | 18u;            /* PKTCNT 1, XFRSIZ 18 */
    DIEPCTL0 |= 0x80000000u;                 /* EPENA */
    while (!XFR_DONE) { }
    DESC_LEN = 18u;
    __asm__ volatile("bkpt #0");
}
"#;

/// Compile `STM32_F107_USB_FIRMWARE` against the F1 pack headers and run it
/// on the F107 board in two phases: the firmware first soft-resets the OTG
/// controller and arms the device interrupts (it soft-resets wipe the bus
/// events, so the host stimulus has to arrive afterwards), then the injected
/// bus reset plus `GET_DESCRIPTOR` SETUP stage is served by the ISR. Returns
/// the four RAM snapshots and the descriptor bytes the host drained. `None`
/// means the toolchain or pack was unavailable.
fn run_usb_firmware() -> Option<(u32, u32, u32, u32, Vec<u8>)> {
    let includes = [
        "../packs/Keil.STM32F1xx_DFP/Device/Include",
        "../packs/STM32F4xx_CMSIS/CMSIS/Core/Include",
    ];
    let mut include_paths = Vec::new();
    for rel in includes {
        let include = PathBuf::from(env!("CARGO_MANIFEST_DIR")).join(rel);
        if !include.is_dir() {
            eprintln!(
                "skipping usb test: pack include dir {} not found",
                include.display()
            );
            return None;
        }
        include_paths.push(
            include
                .to_str()
                .expect("pack include path is not UTF-8")
                .to_owned(),
        );
    }
    let include_refs: Vec<&str> = include_paths.iter().map(String::as_str).collect();
    let (code, symbols) = match build_firmware_with_includes(STM32_F107_USB_FIRMWARE, &include_refs)
    {
        Ok(image) => image,
        Err(why) => {
            eprintln!("skipping usb test: {why}");
            return None;
        }
    };
    let entry = *symbols.get("reset").expect("no reset symbol");
    let irq = *symbols
        .get("OTG_FS_IRQHandler")
        .expect("no OTG_FS_IRQHandler symbol");
    assert!(!code.is_empty(), "compiled .text must not be empty");

    let mut m = Machine::new(board::stm32f107());
    m.load_image(&load_flat(USB_CODE_BASE, &code));
    {
        let mem = m.core.mem();
        mem.write_word(FLASH, INIT_SP).unwrap();
        mem.write_word(FLASH + 4, (USB_CODE_BASE + entry) | 1)
            .unwrap();
        // Vector 83 = OTG_FS IRQ 67 at FLASH + 83 * 4.
        mem.write_word(FLASH + 83 * 4, (USB_CODE_BASE + irq) | 1)
            .unwrap();
    }
    m.reset().expect("reset from vector table");
    // Phase 1: the firmware soft-resets the controller and waits for the
    // SETUP stage (the soft reset wiped any earlier bus events).
    let err = m.run(200_000);
    assert_eq!(err, Err(HaltCause::CycleBudgetExhausted));
    assert_eq!(
        m.core.mem().read_word(board::RAM + 0x10).unwrap(),
        1u32,
        "the controller was configured before waiting"
    );
    // Phase 2: host bus reset, then the GET_DESCRIPTOR SETUP packet.
    let reset_frame: &[u8] = &[0x00, 0x00];
    let setup_frame: &[u8] = &[0x02, 8, 0x80, 0x06, 0x00, 0x01, 0x00, 0x00, 0x12, 0x00];
    for frame in [reset_frame, setup_frame] {
        for &byte in frame {
            for device in m.core.mem().devices_mut() {
                device.drive_inputs(u32::from(byte));
            }
        }
    }
    // Phase 3: the ISR stages the SETUP, the firmware answers with the
    // 18-byte device descriptor, and the handshake completes at `bkpt`.
    let err = m.run(200_000);
    assert_eq!(err, Err(HaltCause::NonThumbTarget));
    let enum_done = m.core.mem().read_word(board::RAM).unwrap();
    let in_ready = m.core.mem().read_word(board::RAM + 4).unwrap();
    let xfr_done = m.core.mem().read_word(board::RAM + 8).unwrap();
    let desc_len = m.core.mem().read_word(board::RAM + 0xC).unwrap();
    let mut tx = Vec::new();
    for device in m.core.mem().devices_mut() {
        tx.extend(device.drain_output());
    }
    Some((enum_done, in_ready, xfr_done, desc_len, tx))
}

/// On the STM32F107 board, CMSIS firmware enumerated over `OTG_FS` answers a
/// `GET_DESCRIPTOR` SETUP packet: the RX FIFO pops the 8 setup bytes, the
/// `STUP` latch arms the endpoint, and the 18-byte device descriptor is
/// drained to the host channel through the `OTG_FS` interrupt.
#[test]
fn stm32f107_firmware_answers_usb_descriptor() {
    let Some((enum_done, in_ready, xfr_done, desc_len, tx)) = run_usb_firmware() else {
        return; // skipped
    };
    assert_eq!(enum_done, 1, "ENUMDNE was latched after the bus reset");
    assert_eq!(in_ready, 1, "the SETUP stage was staged on endpoint 0");
    assert_eq!(xfr_done, 1, "the IN transfer completed");
    assert_eq!(desc_len, 18, "the descriptor length was reported");
    // One EVT_IN frame: opcode 0x80, length 18, endpoint 0, then the
    // 18-byte device descriptor (little-endian words 0x02000112, 0x40000000,
    // 0x57100483, 0x02010100, 0x00000100).
    let expected: &[u8] = &[
        0x80, 0x12, 0x00, 0x12, 0x01, 0x00, 0x02, 0x00, 0x00, 0x00, 0x40, 0x83, 0x04, 0x10, 0x57,
        0x00, 0x01, 0x01, 0x02, 0x00, 0x01,
    ];
    assert_eq!(tx, expected, "the device descriptor reached the host");
}

/// Real CMSIS-style firmware against the STM32F107 Ethernet controller: a
/// single self-chained RX descriptor (OWN, 1536-byte buffer) receives a
/// host-injected frame through the `ETH` interrupt (IRQ 61, exception 77),
/// and the received bytes are echoed back through a TX descriptor after a
/// `DMATPDR` poll demand. The ISR mirrors the Keil `EMAC_STM32F10x` driver:
/// read `DMASR`, write-one-to-clear `NIS|RS|TS`, then act on the latches.
const STM32_F107_ETH_FIRMWARE: &str = r#"
#define STM32F10X_CL
#include "stm32f10x.h"

#define RX_DONE (*(volatile unsigned *)0x20000000u)
#define TX_DONE (*(volatile unsigned *)0x20000004u)
#define RX_W0   (*(volatile unsigned *)0x20000008u)
#define RX_W1   (*(volatile unsigned *)0x2000000Cu)

#define RX_RING 0x20000100u
#define RX_BUF  0x20000200u
#define TX_RING 0x20000300u
#define TX_BUF  0x20000400u

void ETH_IRQHandler(void) {
    unsigned dmasr = ETH->DMASR;
    ETH->DMASR = dmasr & (ETH_DMASR_NIS | ETH_DMASR_RS | ETH_DMASR_TS);
    if (dmasr & ETH_DMASR_RS) {
        RX_DONE = 1u;
        RX_W0 = *(volatile unsigned *)RX_BUF;
        RX_W1 = *(volatile unsigned *)(RX_BUF + 4);
    }
    if (dmasr & ETH_DMASR_TS) {
        TX_DONE = 1u;
    }
}

void reset(void) {
    /* 1. One RX descriptor, self-chained, 1536-byte buffer. */
    volatile unsigned *rx = (volatile unsigned *)RX_RING;
    rx[0] = 0x80000000u;              /* OWN */
    rx[1] = 0x4000u | 0x600u;         /* RCH | RBS1 = 1536 */
    rx[2] = RX_BUF;
    rx[3] = RX_RING;

    /* 2. One TX descriptor, self-chained. */
    volatile unsigned *tx = (volatile unsigned *)TX_RING;
    tx[0] = 0x00100000u | 0x20000000u | 0x10000000u; /* TCH | LS | FS */
    tx[1] = 0u;
    tx[2] = TX_BUF;
    tx[3] = TX_RING;

    /* 3. Point the DMA at the rings and arm the interrupts. */
    ETH->DMARDLAR = RX_RING;
    ETH->DMATDLAR = TX_RING;
    ETH->DMASR = 0xFFFFFFFFu;
    ETH->DMAIER = ETH_DMAIER_NISE | ETH_DMAIER_RIE | ETH_DMAIER_TIE;

    /* 4. Receiver and transmitter on, DMA RX and TX started. */
    ETH->MACCR = ETH_MACCR_RE | ETH_MACCR_TE;
    ETH->DMAOMR = ETH_DMAOMR_SR | ETH_DMAOMR_ST;

    /* 5. Enable the ETH IRQ (IRQ 61, exception 77). */
    NVIC->ISER[1] = 1u << (ETH_IRQn - 32);

    /* 6. Wait for the host-injected frame to arrive through the IRQ. */
    while (!RX_DONE) { }

    /* 7. Echo the six received bytes back out through the TX descriptor. */
    {
        volatile unsigned char *s = (volatile unsigned char *)RX_BUF;
        volatile unsigned char *d = (volatile unsigned char *)TX_BUF;
        unsigned i;
        for (i = 0; i < 6; ++i) d[i] = s[i];
    }
    tx[1] = 6u;                          /* TBS1 */
    tx[0] |= 0x80000000u;                /* OWN */
    ETH->DMASR = ETH_DMASR_TPSS;         /* clear the TX process-stopped bit */
    ETH->DMATPDR = 0u;                   /* poll demand */
    while (!TX_DONE) { }

    __asm__ volatile("bkpt #0");
}
"#;

/// Compile `STM32_F107_ETH_FIRMWARE` against the F1 pack headers and run it
/// on the F107 board: the firmware arms the DMA rings and waits, the injected
/// RX frame wakes `ETH_IRQHandler`, and the echoed bytes come back through the
/// TX path. Returns the two RX snapshot words, the two completion flags, and
/// the transmitted host frame. `None` means the toolchain or pack was
/// unavailable.
fn run_eth_firmware() -> Option<(u32, u32, u32, u32, Vec<u8>)> {
    let includes = [
        "../packs/Keil.STM32F1xx_DFP/Device/Include",
        "../packs/STM32F4xx_CMSIS/CMSIS/Core/Include",
    ];
    let mut include_paths = Vec::new();
    for rel in includes {
        let include = PathBuf::from(env!("CARGO_MANIFEST_DIR")).join(rel);
        if !include.is_dir() {
            eprintln!(
                "skipping eth test: pack include dir {} not found",
                include.display()
            );
            return None;
        }
        include_paths.push(
            include
                .to_str()
                .expect("pack include path is not UTF-8")
                .to_owned(),
        );
    }
    let include_refs: Vec<&str> = include_paths.iter().map(String::as_str).collect();
    let (code, symbols) = match build_firmware_with_includes(STM32_F107_ETH_FIRMWARE, &include_refs)
    {
        Ok(image) => image,
        Err(why) => {
            eprintln!("skipping eth test: {why}");
            return None;
        }
    };
    let entry = *symbols.get("reset").expect("no reset symbol");
    let irq = *symbols
        .get("ETH_IRQHandler")
        .expect("no ETH_IRQHandler symbol");
    assert!(!code.is_empty(), "compiled .text must not be empty");

    let mut m = Machine::new(board::stm32f107());
    m.load_image(&load_flat(USB_CODE_BASE, &code));
    {
        let mem = m.core.mem();
        mem.write_word(FLASH, INIT_SP).unwrap();
        mem.write_word(FLASH + 4, (USB_CODE_BASE + entry) | 1)
            .unwrap();
        // Vector 77 = ETH IRQ 61 at FLASH + 77 * 4. Loaded at `USB_CODE_BASE`
        // (0x1000) so the vector-table write cannot clobber the code image.
        mem.write_word(FLASH + 77 * 4, (USB_CODE_BASE + irq) | 1)
            .unwrap();
    }
    m.reset().expect("reset from vector table");
    // Host stimulus: a 6-byte frame on the channel (opcode 0x01, len 6).
    for byte in [0x01u8, 6, 0, 0x41, 0x42, 0x43, 0x44, 0x45, 0x46] {
        for device in m.core.mem().devices_mut() {
            device.drive_inputs(u32::from(byte));
        }
    }
    let err = m.run(200_000);
    assert_eq!(err, Err(HaltCause::NonThumbTarget));
    let rx_done = m.core.mem().read_word(board::RAM).unwrap();
    let tx_done = m.core.mem().read_word(board::RAM + 4).unwrap();
    let rx_w0 = m.core.mem().read_word(board::RAM + 8).unwrap();
    let rx_w1 = m.core.mem().read_word(board::RAM + 0xC).unwrap();
    let mut tx = Vec::new();
    for device in m.core.mem().devices_mut() {
        tx.extend(device.drain_output());
    }
    Some((rx_w0, rx_w1, rx_done, tx_done, tx))
}

/// On the STM32F107 board, CMSIS firmware drives the Ethernet DMA rings: the
/// injected RX frame lands in the buffer through the `ETH` interrupt, and the
/// echoed bytes return over the TX path to the host channel.
#[test]
fn stm32f107_firmware_talks_ethernet() {
    let Some((rx_w0, rx_w1, rx_done, tx_done, tx)) = run_eth_firmware() else {
        return; // skipped
    };
    assert_eq!(rx_done, 1, "the RX interrupt fired");
    assert_eq!(tx_done, 1, "the TX interrupt fired");
    // The injected frame bytes 0x41..0x46 landed in the RX buffer.
    assert_eq!(rx_w0, 0x4443_4241, "first received word");
    assert_eq!(rx_w1, 0x0000_4645, "second received word");
    // The echoed frame reached the host channel: EVT_TX, length 6, the bytes.
    let expected: &[u8] = &[0x80, 6, 0, 0x41, 0x42, 0x43, 0x44, 0x45, 0x46];
    assert_eq!(tx, expected, "the echoed frame reached the host");
}

/// Full SoC gap-fill: PWR/BKP/CRC/DAC/RTC/SDIO together on STM32F103.
#[test]
fn stm32f103_full_soc_gap_fill() {
    const FW: &str = r#"
#define PWR_CR   0x40007000u
#define BKP_DR1  0x40006C04u
#define CRC_DR   0x40023000u
#define CRC_CR   0x40023008u
#define DAC_CR   0x40007400u
#define DAC_DHR12R1 0x40007408u
#define DAC_DOR1 0x4000742Cu
#define DAC_SWTRIGR 0x40007404u
#define RTC_CRH  0x40002800u
#define RTC_CRL  0x40002804u
#define RTC_PRLH 0x40002808u
#define RTC_PRLL 0x4000280Cu
#define RTC_CNTH 0x40002818u
#define RTC_CNTL 0x4000281Cu
#define RTC_ALRH 0x40002820u
#define RTC_ALRL 0x40002824u
#define SDIO_POWER 0x40018000u
#define SDIO_CLKCR 0x40018004u
#define SDIO_ARG   0x40018008u
#define SDIO_CMD   0x4001800Cu
#define SDIO_RESPCMD 0x40018010u
#define SDIO_RESP1 0x40018014u
#define SDIO_STA   0x40018034u
#define OUT 0x20000000u

void reset(void) {
    *(volatile unsigned *)PWR_CR |= (1u<<8);
    *(volatile unsigned *)BKP_DR1 = 0x1234u;
    *(volatile unsigned *)CRC_CR = 1u;
    *(volatile unsigned *)CRC_DR = 0x12345678u;
    unsigned crc = *(volatile unsigned *)CRC_DR;
    *(volatile unsigned *)DAC_CR = 0x1u;
    *(volatile unsigned *)DAC_DHR12R1 = 0x0ABu;
    unsigned dor = *(volatile unsigned *)DAC_DOR1;
    *(volatile unsigned *)DAC_CR = 0x5u;
    *(volatile unsigned *)DAC_DHR12R1 = 0x0CDu;
    *(volatile unsigned *)DAC_SWTRIGR = 1u;
    unsigned dor2 = *(volatile unsigned *)DAC_DOR1;
    *(volatile unsigned *)RTC_CRL |= (1u<<4);
    *(volatile unsigned *)RTC_PRLH = 0;
    *(volatile unsigned *)RTC_PRLL = 1;
    *(volatile unsigned *)RTC_CNTH = 0;
    *(volatile unsigned *)RTC_CNTL = 0;
    *(volatile unsigned *)RTC_ALRH = 0;
    *(volatile unsigned *)RTC_ALRL = 2;
    *(volatile unsigned *)RTC_CRH = 2;
    *(volatile unsigned *)RTC_CRL &= ~(1u<<4);
    *(volatile unsigned *)SDIO_POWER = 0x03u;
    *(volatile unsigned *)SDIO_CLKCR = 0x100u;
    *(volatile unsigned *)SDIO_ARG = 0;
    *(volatile unsigned *)SDIO_CMD = 0x400u;
    unsigned sta0 = *(volatile unsigned *)SDIO_STA;
    *(volatile unsigned *)SDIO_CMD = 0x448u;
    unsigned resp = *(volatile unsigned *)SDIO_RESP1;
    *(volatile unsigned *)SDIO_CMD = 0x477u;
    *(volatile unsigned *)SDIO_CMD = 0x4469u;
    unsigned ocr = *(volatile unsigned *)SDIO_RESP1;
    *(volatile unsigned *)OUT = (*(volatile unsigned *)BKP_DR1 == 0x1234u) ? 1u : 0u;
    *(volatile unsigned *)(OUT+4) = (crc != 0xFFFFFFFFu && crc != 0x12345678u) ? 1u : 0u;
    *(volatile unsigned *)(OUT+8) = (dor == 0xABu) ? 1u : 0u;
    *(volatile unsigned *)(OUT+12) = (dor2 == 0xCDu) ? 1u : 0u;
    *(volatile unsigned *)(OUT+16) = (sta0 & (1u<<7)) ? 1u : 0u;
    *(volatile unsigned *)(OUT+20) = (resp == 0x1AAu) ? 1u : 0u;
    *(volatile unsigned *)(OUT+24) = (ocr & 0x80000000u) ? 1u : 0u;
    __asm__ volatile("bkpt #0");
}
"#;
    let (code, symbols) = match build_firmware_v7m_with_includes(FW, &[]) {
        Ok(image) => image,
        Err(why) => {
            eprintln!("skipping full Soc test: {why}");
            return;
        }
    };
    let entry = *symbols.get("reset").expect("no reset symbol");
    let mut m = Machine::armv7m(board::stm32f103());
    m.load_image(&load_flat(CODE_BASE, &code));
    {
        let mem = m.core.mem();
        mem.write_word(board::FLASH, INIT_SP).unwrap();
        mem.write_word(board::FLASH + 4, (CODE_BASE + entry) | 1).unwrap();
    }
    m.reset().expect("reset");
    let err = m.run(50_000);
    assert_eq!(err, Err(HaltCause::NonThumbTarget), "full Soc firmware did not halt, got {err:?}");
    assert_eq!(m.core.mem().read_word(RAM).unwrap(), 1, "BKP DR1 round-trip");
    assert_eq!(m.core.mem().read_word(RAM + 4).unwrap(), 1, "CRC computed");
    assert_eq!(m.core.mem().read_word(RAM + 8).unwrap(), 1, "DAC immediate DOR");
    assert_eq!(m.core.mem().read_word(RAM + 12).unwrap(), 1, "DAC SWTRIG DOR");
    assert_eq!(m.core.mem().read_word(RAM + 16).unwrap(), 1, "SDIO CMDSENT");
    assert_eq!(m.core.mem().read_word(RAM + 20).unwrap(), 1, "SDIO CMD8 RESP");
    assert_eq!(m.core.mem().read_word(RAM + 24).unwrap(), 1, "SDIO ACMD41 OCR ready");
}

